30	/**
31	 * Single idempotent choke point for keeping a paid Minecraft server's DNS
32	 * (`<subdomain>.play.nxeon.cloud`, see lib/game-subdomain-dns.ts) in sync with
33	 * its actual reachable ip:port. Called from every place that can change that
34	 * ip:port: provision() (dedicated-IP servers only — see below), addPortForward/
35	 * deletePortForward (NAT servers), and suspend()/unsuspend().
36	 *
37	 * Never throws — a DNS hiccup must not fail provisioning, a port-forward save,
38	 * or a suspend/unsuspend cycle. Callers fire-and-forget via the SYNC_GAME_DNS
39	 * job (see worker/index.ts) rather than awaiting this inline.
40	 */
41	export async function syncGameServerDns(serverId: string): Promise<void> {
42	  if (SANDBOX) return;
43	  try {
44	    const server = await db.server.findUnique({
45	      where: { id: serverId },
46	      include: {
47	        osTemplate: { select: { family: true } },
48	        gamePlan: { select: { gameFamily: true } },
49	        node: { select: { publicIp: true } },
50	        dedicatedIp: { select: { address: true } },
51	        portForwards: true,
52	      },
53	    });
54	    if (!server || !server.subdomain) return;
55	
56	    const familyLike = server as unknown as { gamePlan?: { gameFamily?: string | null } | null; osTemplate?: { family?: string | null } | null };
57	    if (gameFamilyForServer(familyLike) !== "minecraft") return; // only Minecraft has an SRV-based connect story
58	    const game = gamePortForServer(familyLike);
59	    if (!game) return;
60	
61	    const target = resolveGameServerDnsTarget({
62	      status: server.status,
63	      dedicatedIp: server.dedicatedIp,
64	      portForwards: server.portForwards,
65	      nodePublicIp: server.node?.publicIp,
66	      publicIpEnv: process.env.PUBLIC_IP,
67	      gamePort: game.port,
68	    });
69	
70	    if (target) {
71	      await upsertMinecraftSubdomainDns({ subdomain: server.subdomain, ip: target.ip, port: target.port });
72	    } else {
73	      await deleteMinecraftSubdomainDns(server.subdomain);
74	    }
75	  } catch (e) {
76	    logError("game-subdomain-sync", e, { serverId });
77	  }
78	}
