 * secrets in lib/actions-account.ts, NOT the ephemeral-JWE convention:
 *
 *   - mint(): random 32-byte token, return the raw value ONCE, store only
 *     its SHA-256 hash (`Server.telemetryTokenHash` / `HostingNode.telemetryTokenHash`).
 *   - lookupByToken(): hash the presented token and look the owner up by the
 *     unique hash column — the same shape as PasswordResetToken lookups.
 *
 * There's no rotation UI yet (Phase 2): re-provisioning a server mints a
 * fresh token and overwrites the old hash, which is all we need since a
 * leaked shipper token only grants "post low-value connection-event rows
 * for this one server," not read/write access to anything else.
 */
import { randomBytes, createHash } from "node:crypto";
import { db } from "./db";

export function mintTelemetryToken(): { token: string; hash: string } {
  const token = randomBytes(32).toString("base64url");
  const hash = createHash("sha256").update(token).digest("hex");
  return { token, hash };
}

export function hashTelemetryToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

/**
 * Mint a fresh telemetry token for a server, persist its hash, and return
 * the raw token to embed in that server's cloud-init config. Call this once
 * per (re)provision, right before buildCloudInit() so the config file the
 * agent boots with matches the hash we just stored.
 */
export async function mintServerTelemetryToken(serverId: string): Promise<string> {
  const { token, hash } = mintTelemetryToken();
  await db.server.update({ where: { id: serverId }, data: { telemetryTokenHash: hash } });
  return token;
}

export async function mintHostingNodeTelemetryToken(nodeId: string): Promise<string> {
  const { token, hash } = mintTelemetryToken();
  await db.hostingNode.update({ where: { id: nodeId }, data: { telemetryTokenHash: hash } });
  return token;
}

